using LocalChat;
using System.Text.Json;
int passed=0,failed=0;void Check(bool ok,string name){Console.WriteLine((ok?"PASS ":"FAIL ")+name);if(ok)passed++;else failed++;}
const string goal="Создай сайт и опубликуй на Cloudflare";
string Call(string code)=>JsonSerializer.Serialize(new{tool="mcp_call",server="cloudflare",name="execute",arguments=new{code}});
var h=new MainWindow();int n=0;h.Result=a=>a.arguments.GetProperty("code").GetString()=="broken"?"MCP TOOL FAILED\nTypeError: api.createSite is not a function":"MCP TOOL RESULT: deployed https://fixed.test.workers.dev";
LocalApi.Next=(messages,s)=>{int turn=n++;if(turn>0&&turn<4)Check(messages[0].content.Contains("TypeError"),"actual error pinned in next-step repair prompt "+turn);return turn<3?Call("broken"):turn==3?Call("corrected publish code"):"done";};
var reply=await h.Run(goal);Check(h.Executed.Count(a=>a.arguments.GetProperty("code").GetString()=="broken")==1,"same failed mutation sent only once, not twice before third-step stop");Check(h.Executed.Any(a=>a.arguments.GetProperty("code").GetString()=="corrected publish code"),"third duplicate is repaired internally; corrected call can still execute");Check(!reply.TaskPending&&reply.Text.Contains("fixed.test.workers.dev"),"corrected provider receipt completes without pressing continue");Check(h.Log.Any(x=>x.Contains("TypeError")),"actual provider error visible in work journal");
h=new();var task=new AgentTask{ChatId=h.current.Id,Goal=goal,Status="paused"};var bad=WorkspaceCore.ParseTool(Call("broken"))!;var st=task.Begin(bad);task.End(st,"MCP TOOL FAILED\nSyntaxError: Unexpected token import");h.PutCheckpoint(task);n=0;h.Result=_=>"MCP TOOL RESULT: deployed https://resume.test.workers.dev";
LocalApi.Next=(m,s)=>{Check(m[0].content.Contains("SyntaxError"),"failure cause survives checkpoint resume");return n++ switch{0=>Call("broken"),1=>Call("fixed after reading provider docs"),_=>"done"};};reply=await h.Run("продолжай");Check(h.Executed.Count==1&&h.Executed[0].arguments.GetProperty("code").GetString()!="broken","resume does not repeat the same known failed write");Check(reply.Text.Contains("resume.test.workers.dev"),"resume can progress with a corrected call");
h=new();h.Result=_=>"MCP TOOL FAILED\nCloudflare error 10000: Authentication error";LocalApi.Next=(_,_)=>Call("broken");reply=await h.Run(goal);Check(h.Executed.Count==1,"unrepairable repeat bounded without re-sending writes");Check(reply.Text.Contains("Authentication error"),"pause contains actual provider failure, not generic no progress");Check(!reply.TaskPending&&reply.TaskStatus=="paused","no automatic resume control promising to solve unchanged failure");Check(!reply.Text.Contains("«Продолжай»"),"no misleading generic continue instruction after unrepaired error");
h=new();n=0;h.Result=a=>a.arguments.GetProperty("code").GetString()=="attempt5"?"MCP TOOL RESULT: deployed https://fifth.test.workers.dev":"MCP TOOL FAILED\nSyntaxError: corrected attempt still invalid";LocalApi.Next=(_,_)=>n<5?Call("attempt"+(++n)):"done";reply=await h.Run(goal);Check(h.Executed.Count==5&&!reply.TaskPending,"distinct correction attempts are not stopped by old three-error budget");
h=new();h.Result=_=>"MCP TOOL FAILED\nAuthentication error Authorization: Bearer private317";LocalApi.Next=(_,_)=>Call("broken");reply=await h.Run(goal);Check(!reply.Text.Contains("private317")&&!h.Log.Any(x=>x.Contains("private317")),"known authorization value not exposed in pause or log");Check(!reply.ToolResults.Any(x=>x.Contains("private317")),"known authorization value redacted in displayed tool results");
// The repair budget remains finite; it is not an infinite tool loop.
h=new();n=0;h.Result=_=>"MCP TOOL FAILED\nSyntaxError: still invalid";LocalApi.Next=(_,_)=>Call("different correction "+(++n));reply=await h.Run(goal);Check(h.Executed.Count==6,"distinct MCP error repair budget bounded at six actual errors");Check(!reply.TaskPending&&reply.TaskStatus=="paused"&&reply.Text.Contains("SyntaxError"),"repair exhaustion preserves real cause without automatic resume");
// A transport failure can follow a committed write: never replay the uncertain operation.
h=new();n=0;h.Result=_=>throw new IOException("connection lost after sending");LocalApi.Next=(_,_)=>Call("uncertain write");reply=await h.Run(goal);Check(h.Executed.Count==1&&h.Checkpoint!.Steps.Any(x=>x.State=="pending"),"unknown transport outcome still protected from write replay");
Check(AgentTask.ErrorText("access_token=private318 https://name:pass@example.com ghp_private319").Contains("private318")==false,"known token and URL credential redaction");
Console.WriteLine($"{passed} passed; {failed} failed");Environment.ExitCode=failed==0?0:1;
